"""Bound the odd G2 primary space generated by one lower BMN multiplet."""
from collections import Counter, defaultdict
from itertools import permutations
import json

from verify import HERE, cochains, read


def low_character(maximum):
    """Weight multiplicities at every level from branching GL(3) to GL(2) to GL(1)."""
    shapes, levels = cochains(maximum,"G2")
    weights = defaultdict(Counter)
    shapes_at_level = defaultdict(dict)
    for w in shapes:
        a,b,c = w
        count = sum((-1)**y * chars.get(w,[0])[0] for y,chars in levels.items())
        if count < 0 or sum(w) > 14:
            raise ValueError("Exact even character requires the certified odd vanishing range")
        if count == 0:
            continue
        shapes_at_level[sum(w)][w] = count
        for i in range(b,a+1):
            for j in range(c,b+1):
                for k in range(j,i+1):
                    weights[sum(w)][k,i+j-k,a+b+c-i-j] += count
    return shapes_at_level, weights


def coefficient(target, source, weights):
    degree = sum(target)-sum(source)
    if degree < 0:
        return 0
    rho = (2,1,0)
    shifted = tuple(a+b for a,b in zip(source,rho))
    count = 0
    for w in permutations(shifted):
        sign = (-1)**sum(i<j for n,i in enumerate(w) for j in w[n+1:])
        difference = tuple(a+b-c for a,b,c in zip(target,rho,w))
        count += sign*weights[degree][difference]
    if count < 0:
        raise ArithmeticError("negative tensor-product multiplicity")
    return count


def calculate():
    target = (6,6,6)
    small, weights = low_character(10)
    assert small[0] == {(0,0,0):1} and not small[1]
    assert small[2] == {(2,0,0):1} and small[3] == {(2,1,0):1}
    possibles = []
    for a in range(7):
        for b in range(a+1):
            for c in range(b+1):
                core = (a,b,c)
                if sum(core) < 15:
                    continue
                if coefficient(target,core,weights):
                    possibles.append(core)
    assert possibles == [(6,5,4),(6,6,4),(6,6,6)]
    records = []
    for row in read(HERE/"5690901/exceptional.json")["rows"]:
        bound = -row["primary_euler"][0]
        if bound <= 0:
            continue
        values = [coefficient(tuple(row["weight"]),core,weights) for core in possibles]
        records.append(dict(level=row["level"],target=row["weight"],odd_lower_bound=bound,
                            upper_from_one_generator=values))
    return dict(candidate_generators=possibles,targets=records)


if __name__=="__main__":
    print(json.dumps(calculate(),indent=2))
